```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>DUNE LINE — Overnight Desert-to-Neon Sleeper</title>
<style>
  :root {
    --bg-deep: #07060e;
    --bg-surface: #110e1c;
    --bg-card: rgba(22, 18, 36, 0.72);
    --bg-card-hover: rgba(30, 25, 49, 0.9);
    --sand-gold: #f3a867;
    --sand-amber: #e26d42;
    --neon-cyan: #00f0d6;
    --neon-pink: #ff2a85;
    --neon-violet: #8c42ff;
    --text-main: #f6f3ec;
    --text-muted: #9e97b0;
    --text-dim: #68617a;
    --border-subtle: rgba(243, 168, 103, 0.16);
    --border-neon: rgba(0, 240, 214, 0.35);
    --font-display: 'Iowan Old Style', 'Palatino Linotype', 'URW Palladio L', P052, Georgia, serif;
    --font-sans: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    --font-mono: ui-monospace, 'Cascadia Code', 'Source Code Pro', Menlo, Consolas, monospace;
    --max-w: 1200px;
    --radius-lg: 20px;
    --radius-md: 12px;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    scroll-behavior: smooth;
    background-color: var(--bg-deep);
    color: var(--text-main);
    font-family: var(--font-sans);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
  }

  body {
    overflow-x: hidden;
    background:
      radial-gradient(circle at 15% 8%, rgba(226, 109, 66, 0.12), transparent 38%),
      radial-gradient(circle at 85% 18%, rgba(0, 240, 214, 0.1), transparent 42%),
      radial-gradient(circle at 50% 65%, rgba(140, 66, 255, 0.07), transparent 50%),
      var(--bg-deep);
  }

  a {
    color: inherit;
    text-decoration: none;
  }

  button {
    font-family: inherit;
    cursor: pointer;
    border: none;
    background: none;
  }

  .container {
    width: 100%;
    max-width: var(--max-w);
    margin: 0 auto;
    padding: 0 32px;
  }

  /* Section Eyebrows & Headings */
  .eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: var(--sand-gold);
    margin-bottom: 14px;
  }

  .eyebrow::before {
    content: "";
    display: inline-block;
    width: 24px;
    height: 1px;
    background: linear-gradient(90deg, var(--sand-gold), var(--neon-cyan));
  }

  .section-title {
    font-family: var(--font-display);
    font-weight: 400;
    font-size: clamp(2rem, 3.6vw, 3rem);
    line-height: 1.12;
    letter-spacing: -0.02em;
    color: var(--text-main);
  }

  .section-sub {
    color: var(--text-muted);
    font-size: 1.05rem;
    max-width: 560px;
    margin-top: 14px;
  }

  /* ================= NAVBAR ================= */
  .navbar {
    position: sticky;
    top: 0;
    z-index: 100;
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    background: rgba(7, 6, 14, 0.78);
    border-bottom: 1px solid rgba(255, 255, 255, 0.07);
    transition: border-color 0.3s ease;
  }

  .nav-inner {
    height: 76px;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .brand {
    display: flex;
    align-items: center;
    gap: 12px;
    font-family: var(--font-mono);
    font-weight: 600;
    letter-spacing: 0.22em;
    font-size: 0.95rem;
    color: var(--text-main);
  }

  .brand-mark {
    width: 36px;
    height: 36px;
    flex-shrink: 0;
  }

  .nav-links {
    display: flex;
    align-items: center;
    gap: 36px;
    list-style: none;
  }

  .nav-links a {
    font-size: 0.9rem;
    color: var(--text-muted);
    letter-spacing: 0.03em;
    transition: color 0.2s ease;
    position: relative;
  }

  .nav-links a:hover {
    color: var(--text-main);
  }

  .nav-links a::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: -6px;
    width: 0%;
    height: 1px;
    background: linear-gradient(90deg, var(--sand-gold), var(--neon-cyan));
    transition: width 0.25s ease;
  }

  .nav-links a:hover::after {
    width: 100%;
  }

  .nav-cta {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 10px 20px;
    border-radius: 999px;
    font-size: 0.85rem;
    font-weight: 600;
    letter-spacing: 0.04em;
    color: var(--bg-deep);
    background: linear-gradient(135deg, var(--sand-gold) 0%, #ffd29d 48%, var(--neon-cyan) 100%);
    box-shadow: 0 0 24px rgba(243, 168, 103, 0.25);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
  }

  .nav-cta:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 28px rgba(0, 240, 214, 0.38);
  }

  .mobile-toggle {
    display: none;
    color: var(--text-main);
    padding: 8px;
  }

  /* ================= HERO ================= */
  .hero {
    position: relative;
    padding: 64px 0 88px;
    overflow: hidden;
  }

  .hero-grid {
    display: grid;
    grid-template-columns: 1.05fr 0.95fr;
    gap: 48px;
    align-items: center;
  }

  .route-badge {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 7px 14px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid var(--border-subtle);
    font-family: var(--font-mono);
    font-size: 0.74rem;
    letter-spacing: 0.1em;
    color: var(--text-muted);
    margin-bottom: 24px;
  }

  .route-badge .dot-sand {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--sand-gold);
    box-shadow: 0 0 8px var(--sand-gold);
  }

  .route-badge .dot-neon {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--neon-cyan);
    box-shadow: 0 0 8px var(--neon-cyan);
  }

  .hero-title {
    font-family: var(--font-display);
    font-weight: 400;
    font-size: clamp(2.75rem, 5vw, 4.45rem);
    line-height: 1.04;
    letter-spacing: -0.025em;
    margin-bottom: 22px;
  }

  .hero-title .grad-sand {
    background: linear-gradient(95deg, #ffe3c2, var(--sand-gold), var(--sand-amber));
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }

  .hero-title .grad-neon {
    background: linear-gradient(95deg, var(--neon-cyan), #72efdd, var(--neon-pink));
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }

  .hero-lead {
    font-size: 1.12rem;
    color: var(--text-muted);
    max-width: 510px;
    margin-bottom: 34px;
    line-height: 1.65;
  }

  .hero-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 16px;
    margin-bottom: 42px;
  }

  .btn-primary {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 15px 28px;
    border-radius: 999px;
    background: linear-gradient(135deg, var(--sand-amber), var(--sand-gold));
    color: #0b0812;
    font-weight: 700;
    font-size: 0.95rem;
    letter-spacing: 0.02em;
    box-shadow: 0 10px 30px rgba(226, 109, 66, 0.3);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
  }

  .btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 14px 36px rgba(243, 168, 103, 0.45);
  }

  .btn-secondary {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 14px 26px;
    border-radius: 999px;
    border: 1px solid rgba(0, 240, 214, 0.35);
    background: rgba(0, 240, 214, 0.05);
    color: var(--neon-cyan);
    font-weight: 500;
    font-size: 0.95rem;
    transition: background 0.2s ease, border-color 0.2s ease;
  }

  .btn-secondary:hover {
    background: rgba(0, 240, 214, 0.12);
    border-color: var(--neon-cyan);
  }

  .hero-stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
    padding-top: 26px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    max-width: 490px;
  }

  .stat-val {
    font-family: var(--font-mono);
    font-size: 1.3rem;
    font-weight: 600;
    color: var(--text-main);
  }

  .stat-label {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--text-dim);
    margin-top: 2px;
  }

  /* Hero Art Frame */
  .hero-art-wrap {
    position: relative;
  }

  .hero-art-card {
    position: relative;
    border-radius: 26px;
    overflow: hidden;
    border: 1px solid rgba(255, 255, 255, 0.12);
    background: #0b0818;
    box-shadow:
      0 30px 80px rgba(0, 0, 0, 0.7),
      0 0 60px rgba(0, 240, 214, 0.1),
      inset 0 1px 0 rgba(255, 255, 255, 0.15);
  }

  .hero-svg {
    display: block;
    width: 100%;
    height: auto;
  }

  /* Train light pulse animation inside SVG */
  @keyframes pulseGlow {
    0%, 100% { opacity: 0.75; }
    50% { opacity: 1; }
  }

  @keyframes streakMove {
    0% { transform: translateX(0); opacity: 0.5; }
    50% { opacity: 0.95; }
    100% { transform: translateX(-14px); opacity: 0.5; }
  }

  @keyframes twinkle {
    0%, 100% { opacity: 0.3; }
    50% { opacity: 1; }
  }

  .svg-twinkle {
    animation: twinkle 3.6s infinite ease-in-out;
  }

  .svg-twinkle-delayed {
    animation: twinkle 4.4s infinite 1.8s ease-in-out;
  }

  .svg-neon-pulse {
    animation: pulseGlow 2.8s infinite ease-in-out;
  }

  .svg-train-streak {
    animation: streakMove 3s infinite alternate ease-in-out;
  }

  .telemetry-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 20px;
    background: rgba(11, 9, 22, 0.92);
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--text-muted);
    letter-spacing: 0.08em;
  }

  .telemetry-live {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    color: var(--neon-cyan);
  }

  .telemetry-live::before {
    content: "";
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--neon-cyan);
    box-shadow: 0 0 8px var(--neon-cyan);
    animation: pulseGlow 1.5s infinite;
  }

  /* ================= FEATURES ================= */
  .features {
    padding: 96px 0;
    position: relative;
  }

  .section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    gap: 32px;
    margin-bottom: 56px;
  }

  .features-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 28px;
  }

  .feature-card {
    background: var(--bg-card);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: var(--radius-lg);
    padding: 34px 30px;
    position: relative;
    overflow: hidden;
    transition: transform 0.3s ease, border-color 0.3s ease, background 0.3s ease;
  }

  .feature-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 2px;
    background: linear-gradient(90deg, transparent, var(--sand-gold), var(--neon-cyan), transparent);
    opacity: 0.45;
    transition: opacity 0.3s ease;
  }

  .feature-card:hover {
    transform: translateY(-6px);
    background: var(--bg-card-hover);
    border-color: rgba(243, 168, 103, 0.3);
  }

  .feature-card:hover::before {
    opacity: 1;
  }

  .feature-illus {
    width: 64px;
    height: 64px;
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.08);
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 26px;
  }

  .feature-num {
    position: absolute;
    top: 32px;
    right: 28px;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--text-dim);
    letter-spacing: 0.14em;
  }

  .feature-card h3 {
    font-family: var(--font-display);
    font-weight: 400;
    font-size: 1.45rem;
    margin-bottom: 12px;
    color: var(--text-main);
  }

  .feature-card p {
    color: var(--text-muted);
    font-size: 0.95rem;
    line-height: 1.65;
    margin-bottom: 22px;
  }

  .feature-spec {
    display: inline-block;
    font-family: var(--font-mono);
    font-size: 0.73rem;
    letter-spacing: 0.08em;
    color: var(--sand-gold);
    padding: 5px 10px;
    border-radius: 6px;
    background: rgba(243, 168, 103, 0.08);
    border: 1px solid rgba(243, 168, 103, 0.18);
  }

  /* ================= TIMETABLE ================= */
  .timetable-section {
    padding: 96px 0;
  }

  .board-shell {
    background: linear-gradient(180deg, rgba(20, 17, 34, 0.92), rgba(11, 9, 21, 0.96));
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 24px;
    overflow: hidden;
    box-shadow: 0 28px 70px rgba(0, 0, 0, 0.55);
  }

  .board-topbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 16px;
    padding: 22px 30px;
    background: rgba(255, 255, 255, 0.025);
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  }

  .board-station {
    display: flex;
    align-items: center;
    gap: 14px;
    font-family: var(--font-mono);
    font-size: 0.82rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
  }

  .board-arrow {
    color: var(--sand-gold);
  }

  .board-clock {
    font-family: var(--font-mono);
    font-size: 0.82rem;
    color: var(--neon-cyan);
    background: rgba(0, 240, 214, 0.08);
    border: 1px solid rgba(0, 240, 214, 0.25);
    padding: 6px 14px;
    border-radius: 999px;
  }

  .table-scroll {
    width: 100%;
    overflow-x: auto;
  }

  .schedule-table {
    width: 100%;
    border-collapse: collapse;
    text-align: left;
    min-width: 780px;
  }

  .schedule-table th {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    color: var(--text-dim);
    padding: 18px 30px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.07);
    font-weight: 500;
  }

  .schedule-table td {
    padding: 24px 30px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    vertical-align: middle;
  }

  .schedule-table tbody tr {
    transition: background 0.2s ease;
  }

  .schedule-table tbody tr:hover {
    background: rgba(255, 255, 255, 0.03);
  }

  .schedule-table tbody tr:last-child td {
    border-bottom: none;
  }

  .train-id {
    font-family: var(--font-mono);
    font-size: 0.8rem;
    color: var(--sand-gold);
    display: block;
    margin-bottom: 3px;
  }

  .train-name {
    font-family: var(--font-display);
    font-size: 1.18rem;
    color: var(--text-main);
  }

  .time-big {
    font-family: var(--font-mono);
    font-size: 1.25rem;
    font-weight: 600;
    letter-spacing: 0.04em;
    color: var(--text-main);
  }

  .time-sub {
    display: block;
    font-size: 0.76rem;
    color: var(--text-dim);
    margin-top: 2px;
  }

  .crossing-note {
    font-size: 0.86rem;
    color: var(--text-muted);
  }

  .status-pill {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 5px 12px;
    border-radius: 999px;
    font-family: var(--font-mono);
    font-size: 0.72rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .status-pill.boarding {
    background: rgba(0, 240, 214, 0.1);
    color: var(--neon-cyan);
    border: 1px solid rgba(0, 240, 214, 0.3);
  }

  .status-pill.limited {
    background: rgba(243, 168, 103, 0.12);
    color: var(--sand-gold);
    border: 1px solid rgba(243, 168, 103, 0.32);
  }

  .status-pill.open {
    background: rgba(255, 255, 255, 0.05);
    color: var(--text-muted);
    border: 1px solid rgba(255, 255, 255, 0.12);
  }

  .status-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: currentColor;
  }

  .row-book-btn {
    padding: 9px 18px;
    border-radius: 999px;
    font-family: var(--font-mono);
    font-size: 0.76rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--text-main);
    border: 1px solid rgba(255, 255, 255, 0.18);
    background: rgba(255, 255, 255, 0.03);
    transition: all 0.2s ease;
  }

  .row-book-btn:hover {
    border-color: var(--neon-cyan);
    color: var(--bg-deep);
    background: var(--neon-cyan);
  }

  /* ================= PRICING ================= */
  .pricing-section {
    padding: 96px 0;
  }

  .pricing-header {
    text-align: center;
    max-width: 640px;
    margin: 0 auto 60px;
  }

  .pricing-header .section-sub {
    margin-left: auto;
    margin-right: auto;
  }

  .pricing-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 28px;
    align-items: stretch;
  }

  .tier-card {
    background: var(--bg-card);
    border: 1px solid rgba(255, 255, 255, 0.09);
    border-radius: 24px;
    padding: 36px 32px;
    display: flex;
    flex-direction: column;
    position: relative;
    transition: transform 0.3s ease, border-color 0.3s ease;
  }

  .tier-card:hover {
    transform: translateY(-5px);
    border-color: rgba(255, 255, 255, 0.2);
  }

  .tier-card.featured {
    background: linear-gradient(165deg, rgba(35, 25, 56, 0.95), rgba(15, 13, 29, 0.96));
    border: 1px solid rgba(0, 240, 214, 0.45);
    box-shadow: 0 24px 64px rgba(0, 240, 214, 0.11);
    transform: translateY(-8px);
  }

  .tier-card.featured:hover {
    transform: translateY(-12px);
  }

  .featured-ribbon {
    position: absolute;
    top: -13px;
    left: 32px;
    padding: 4px 14px;
    border-radius: 999px;
    font-family: var(--font-mono);
    font-size: 0.7rem;
    font-weight: 600;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    background: linear-gradient(90deg, var(--neon-cyan), #6ef7e5);
    color: #07060e;
  }

  .tier-code {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    letter-spacing: 0.16em;
    color: var(--sand-gold);
    text-transform: uppercase;
    margin-bottom: 8px;
  }

  .tier-name {
    font-family: var(--font-display);
    font-size: 1.7rem;
    font-weight: 400;
    margin-bottom: 10px;
  }

  .tier-desc {
    font-size: 0.92rem;
    color: var(--text-muted);
    min-height: 46px;
  }

  .ticket-perf {
    margin: 24px 0;
    border-top: 1px dashed rgba(255, 255, 255, 0.16);
    position: relative;
  }

  .tier-price {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 24px;
  }

  .price-amount {
    font-family: var(--font-display);
    font-size: 2.85rem;
    line-height: 1;
    color: var(--text-main);
  }

  .price-unit {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    color: var(--text-dim);
    text-transform: uppercase;
    letter-spacing: 0.08em;
  }

  .tier-perks {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 13px;
    margin-bottom: 34px;
    flex-grow: 1;
  }

  .tier-perks li {
    display: flex;
    align-items: flex-start;
    gap: 11px;
    font-size: 0.92rem;
    color: var(--text-muted);
  }

  .perk-check {
    color: var(--neon-cyan);
    flex-shrink: 0;
    margin-top: 3px;
  }

  .tier-btn {
    width: 100%;
    padding: 14px 20px;
    border-radius: 12px;
    font-weight: 600;
    font-size: 0.92rem;
    letter-spacing: 0.03em;
    border: 1px solid rgba(255, 255, 255, 0.18);
    color: var(--text-main);
    background: rgba(255, 255, 255, 0.04);
    transition: all 0.2s ease;
  }

  .tier-btn:hover {
    background: rgba(255, 255, 255, 0.11);
    border-color: var(--sand-gold);
  }

  .tier-card.featured .tier-btn {
    background: linear-gradient(135deg, var(--neon-cyan), #4be8d5);
    color: #07060e;
    border-color: transparent;
    box-shadow: 0 8px 24px rgba(0, 240, 214, 0.25);
  }

  .tier-card.featured .tier-btn:hover {
    box-shadow: 0 10px 30px rgba(0, 240, 214, 0.45);
    transform: translateY(-1px);
  }

  /* ================= TESTIMONIAL ================= */
  .testimonial-section {
    padding: 80px 0 110px;
  }

  .quote-panel {
    position: relative;
    border-radius: 28px;
    padding: 64px 72px;
    background:
      radial-gradient(circle at 90% 20%, rgba(255, 42, 133, 0.13), transparent 45%),
      radial-gradient(circle at 10% 85%, rgba(243, 168, 103, 0.14), transparent 45%),
      linear-gradient(145deg, rgba(23, 19, 39, 0.9), rgba(12, 10, 22, 0.95));
    border: 1px solid rgba(255, 255, 255, 0.1);
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 48px;
    align-items: center;
    overflow: hidden;
  }

  .quote-mark {
    font-family: var(--font-display);
    font-size: 4.5rem;
    line-height: 0.7;
    color: var(--sand-gold);
    opacity: 0.55;
    margin-bottom: 18px;
    display: block;
  }

  .quote-text {
    font-family: var(--font-display);
    font-size: clamp(1.35rem, 2.3vw, 1.95rem);
    line-height: 1.42;
    color: var(--text-main);
    margin-bottom: 28px;
    font-style: italic;
  }

  .quote-author {
    display: flex;
    align-items: center;
    gap: 16px;
  }

  .author-avatar {
    width: 52px;
    height: 52px;
    border-radius: 50%;
    flex-shrink: 0;
    border: 1px solid rgba(0, 240, 214, 0.4);
    overflow: hidden;
  }

  .author-name {
    font-weight: 600;
    font-size: 1rem;
    color: var(--text-main);
  }

  .author-role {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    letter-spacing: 0.08em;
    color: var(--text-muted);
    margin-top: 2px;
  }

  .quote-stamp {
    width: 148px;
    height: 148px;
    flex-shrink: 0;
    opacity: 0.9;
  }

  /* ================= FOOTER ================= */
  .footer {
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    background: #05040a;
    padding: 72px 0 40px;
  }

  .footer-top {
    display: grid;
    grid-template-columns: 1.4fr 0.8fr 0.8fr 1.2fr;
    gap: 40px;
    padding-bottom: 56px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  }

  .footer-tagline {
    color: var(--text-muted);
    font-size: 0.92rem;
    margin-top: 16px;
    max-width: 300px;
  }

  .footer-coords {
    margin-top: 20px;
    font-family: var(--font-mono);
    font-size: 0.73rem;
    letter-spacing: 0.1em;
    color: var(--text-dim);
  }

  .footer-col h4 {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--sand-gold);
    margin-bottom: 18px;
  }

  .footer-col ul {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 11px;
  }

  .footer-col a {
    font-size: 0.9rem;
    color: var(--text-muted);
    transition: color 0.2s ease;
  }

  .footer-col a:hover {
    color: var(--neon-cyan);
  }

  .dispatch-form {
    display: flex;
    gap: 8px;
    margin-top: 14px;
  }

  .dispatch-input {
    flex: 1;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 10px;
    padding: 11px 14px;
    color: var(--text-main);
    font-size: 0.88rem;
    outline: none;
    transition: border-color 0.2s ease;
  }

  .dispatch-input:focus {
    border-color: var(--neon-cyan);
  }

  .dispatch-btn {
    padding: 11px 18px;
    border-radius: 10px;
    background: rgba(243, 168, 103, 0.16);
    border: 1px solid rgba(243, 168, 103, 0.4);
    color: var(--sand-gold);
    font-family: var(--font-mono);
    font-size: 0.78rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    transition: all 0.2s ease;
  }

  .dispatch-btn:hover {
    background: var(--sand-gold);
    color: #07060e;
  }

  .dispatch-msg {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--neon-cyan);
    margin-top: 10px;
    min-height: 18px;
  }

  .footer-bottom {
    padding-top: 28px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 16px;
    font-size: 0.82rem;
    color: var(--text-dim);
  }

  .route-line-mini {
    display: flex;
    align-items: center;
    gap: 10px;
    font-family: var(--font-mono);
    font-size: 0.74rem;
  }

  .route-line-mini span.bar {
    width: 48px;
    height: 2px;
    background: linear-gradient(90deg, var(--sand-gold), var(--neon-pink), var(--neon-cyan));
  }

  /* ================= BOOKING MODAL ================= */
  .modal-backdrop {
    position: fixed;
    inset: 0;
    z-index: 200;
    background: rgba(4, 3, 9, 0.82);
    backdrop-filter: blur(10px);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.25s ease;
  }

  .modal-backdrop.active {
    opacity: 1;
    pointer-events: auto;
  }

  .modal-card {
    width: 100%;
    max-width: 480px;
    background: #131022;
    border: 1px solid rgba(0, 240, 214, 0.35);
    border-radius: 22px;
    padding: 32px;
    box-shadow: 0 30px 80px rgba(0, 0, 0, 0.8);
    transform: translateY(14px);
    transition: transform 0.25s ease;
  }

  .modal-backdrop.active .modal-card {
    transform: translateY(0);
  }

  .modal-head {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 22px;
  }

  .modal-head h3 {
    font-family: var(--font-display);
    font-size: 1.55rem;
    font-weight: 400;
  }

  .modal-close {
    color: var(--text-muted);
    font-size: 1.4rem;
    line-height: 1;
    padding: 4px 8px;
  }

  .modal-close:hover {
    color: var(--text-main);
  }

  .form-group {
    margin-bottom: 16px;
  }

  .form-group label {
    display: block;
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--text-muted);
    margin-bottom: 6px;
  }

  .form-control {
    width: 100%;
    padding: 12px 14px;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.14);
    background: rgba(255, 255, 255, 0.04);
    color: var(--text-main);
    font-family: var(--font-sans);
    font-size: 0.92rem;
    outline: none;
  }

  .form-control option {
    background: #131022;
    color: var(--text-main);
  }

  .form-control:focus {
    border-color: var(--neon-cyan);
  }

  .modal-submit {
    width: 100%;
    margin-top: 10px;
    padding: 14px;
    border-radius: 12px;
    background: linear-gradient(135deg, var(--sand-gold), var(--neon-cyan));
    color: #07060e;
    font-weight: 700;
    font-size: 0.95rem;
  }

  .booking-success {
    display: none;
    text-align: center;
    padding: 18px 0 6px;
  }

  .booking-success h4 {
    font-family: var(--font-display);
    font-size: 1.5rem;
    margin-bottom: 8px;
    color: var(--neon-cyan);
  }

  .booking-success p {
    color: var(--text-muted);
    font-size: 0.92rem;
    margin-bottom: 16px;
  }

  .ticket-ref {
    display: inline-block;
    font-family: var(--font-mono);
    padding: 8px 16px;
    border-radius: 8px;
    background: rgba(0, 240, 214, 0.1);
    border: 1px dashed var(--neon-cyan);
    color: var(--neon-cyan);
    font-size: 0.85rem;
    letter-spacing: 0.12em;
  }

  /* ================= RESPONSIVE ================= */
  @media (max-width: 1024px) {
    .hero-grid {
      grid-template-columns: 1fr;
      gap: 44px;
    }
    .features-grid,
    .pricing-grid {
      grid-template-columns: 1fr;
      max-width: 580px;
      margin: 0 auto;
    }
    .tier-card.featured {
      transform: none;
    }
    .quote-panel {
      grid-template-columns: 1fr;
      padding: 44px 36px;
      text-align: left;
    }
    .quote-stamp {
      display: none;
    }
    .footer-top {
      grid-template-columns: 1fr 1fr;
    }
  }

  @media (max-width: 768px) {
    .container {
      padding: 0 20px;
    }
    .nav-links,
    .nav-cta-desktop {
      display: none;
    }
    .mobile-toggle {
      display: block;
    }
    .navbar.menu-open .nav-links {
      display: flex;
      flex-direction: column;
      position: absolute;
      top: 76px;
      left: 0;
      right: 0;
      background: rgba(11, 9, 22, 0.98);
      padding: 24px;
      gap: 20px;
      border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    }
    .section-header {
      flex-direction: column;
      align-items: flex-start;
      gap: 12px;
    }
    .footer-top {
      grid-template-columns: 1fr;
    }
  }
</style>
</head>
<body>

  <!-- ================= NAVIGATION ================= -->
