  <script>
    // Mobile Menu Toggle
    const navbar = document.getElementById('navbar');
    const mobileToggle = document.getElementById('mobileToggle');
    const navLinks = document.getElementById('navLinks');

    mobileToggle.addEventListener('click', () => {
      navbar.classList.toggle('menu-open');
    });

    navLinks.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => navbar.classList.remove('menu-open'));
    });

    // Live Station Clock (Sandstone Gate Time)
    const liveClock = document.getElementById('liveClock');
    function updateClock() {
      const now = new Date();
      const hh = String(now.getHours()).padStart(2, '0');
      const mm = String(now.getMinutes()).padStart(2, '0');
      const ss = String(now.getSeconds()).padStart(2, '0');
      liveClock.textContent = `STATION TIME · ${hh}:${mm}:${ss}`;
    }
    updateClock();
    setInterval(updateClock, 1000);

    // Booking Modal Logic
    const modal = document.getElementById('bookingModal');
    const bookingForm = document.getElementById('bookingForm');
    const bookingSuccess = document.getElementById('bookingSuccess');
    const selectTier = document.getElementById('selectTier');
    const selectDeparture = document.getElementById('selectDeparture');

    function openBooking(tierHint, departureHint) {
      bookingForm.style.display = 'block';
      bookingSuccess.style.display = 'none';

      if (tierHint) {
        for (const opt of selectTier.options) {
          if (opt.value.toLowerCase().includes(tierHint.toLowerCase().split(' ')[0])) {
            selectTier.value = opt.value;
            break;
          }
        }
      }

      if (departureHint) {
        for (const opt of selectDeparture.options) {
          if (opt.value.includes(departureHint.slice(0, 5))) {
            selectDeparture.value = opt.value;
            break;
          }
        }
      }

      modal.classList.add('active');
    }

    function closeBooking() {
      modal.classList.remove('active');
    }

    modal.addEventListener('click', (e) => {
      if (e.target === modal) closeBooking();
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') closeBooking();
    });

    bookingForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const name = document.getElementById('passengerName').value.trim() || 'Traveler';
      const dep = selectDeparture.value;
      const tier = selectTier.value;
      const code = 'DL-' + Math.floor(1000 + Math.random() * 9000) + '-NV9';

      document.getElementById('bookingSummaryText').textContent =
        `${name}, your ${tier} on the ${dep} crossing is reserved at Sandstone Gate Platform 04.`;
      document.getElementById('ticketRefCode').textContent = `KEY · ${code}`;

      bookingForm.style.display = 'none';
      bookingSuccess.style.display = 'block';
    });

    // Newsletter Dispatch Form
    const dispatchForm = document.getElementById('dispatchForm');
    const dispatchMsg = document.getElementById('dispatchMsg');
    dispatchForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const email = document.getElementById('dispatchEmail').value;
      dispatchMsg.textContent = `✓ Clear-sky alerts routed to ${email}`;
      dispatchForm.reset();
    });
  </script>
